sub:assertion {
  <https://w3id.org/delphi/resource/claim/high-composite-with-failing-gates> a delphi:Claim ;
    rdfs:label "On the winged-zebrafish run the scorer's composite reads 0.878 and plausible, yet two of the five named gates fail, two cannot be assessed, and the validator withholds the word validated." ;
    dct:description "STATUS: an observation from one fixture run (swarm/benchmark/fixtures/gt-l4-t1.json), generated=winged-zebrafish against base=zebrafish-adult for the desired phenotype of gliding at least 5 m from a 1 m launch and surviving 10-30 C as an adult. Gates: phenotype_similarity pass; functional_resolution fail; physics_check fail; genotype_similarity cannot-assess; lean_check cannot-assess. The scorer composite of 0.878 (plausible true, version 1.0.0) is carried for reference only and no gate feeds it. The validator set word_validated_withheld to true and the CLI exited 1 (sim-engine/validate-cli.mjs:17). DOES NOT ESTABLISH: that the winged zebrafish is valid or invalid as a design, that the composite is generally unreliable beyond this single run, that the two unassessed gates would pass or fail, or anything about the cell, tissue and organ_system scales, which were not assessed. No sequence was compared at any locus." ;
    delphi:hasEvidence <https://w3id.org/delphi/resource/evidence/high-composite-with-failing-gates> .

  <https://w3id.org/delphi/resource/evidence/high-composite-with-failing-gates> a delphi:EvidenceItem ;
    rdfs:label "Gate results, composite and withheld verdict for the winged-zebrafish run in gt-l4-t1.json" ;
    dct:description "Values read from swarm/benchmark/fixtures/gt-l4-t1.json (results, composite_score_from_the_scorer, verdict.word_validated_withheld, verdict.withheld_because, verdict.scales_not_assessed) and the exit-code rule at sim-engine/validate-cli.mjs:17. Each node below is one reported number." ;
    schema:additionalProperty sub:pv-composite, sub:pv-version, sub:pv-failed, sub:pv-unassessed-gates, sub:pv-unassessed-scales, sub:pv-exit .

  sub:pv-composite a schema:PropertyValue ;
    schema:propertyID "scorer_composite" ;
    schema:value "0.878"^^xsd:decimal ;
    schema:description "Scorer composite on this run, flagged plausible true; reference only, not the report's verdict, no gate feeds it. Source: swarm/benchmark/fixtures/gt-l4-t1.json#composite_score_from_the_scorer" .

  sub:pv-version a schema:PropertyValue ;
    schema:propertyID "scorer_version" ;
    schema:value "1.0.0" ;
    schema:description "Version string of the scorer that produced the composite. Source: swarm/benchmark/fixtures/gt-l4-t1.json#composite_score_from_the_scorer" .

  sub:pv-failed a schema:PropertyValue ;
    schema:propertyID "gates_failed" ;
    schema:value "2"^^xsd:integer ;
    schema:description "Gates that failed: functional_resolution and physics_check. Source: swarm/benchmark/fixtures/gt-l4-t1.json#results" .

  sub:pv-unassessed-gates a schema:PropertyValue ;
    schema:propertyID "gates_cannot_assess" ;
    schema:value "2"^^xsd:integer ;
    schema:description "Gates that could not be assessed: genotype_similarity and lean_check. Source: swarm/benchmark/fixtures/gt-l4-t1.json#verdict.withheld_because" .

  sub:pv-unassessed-scales a schema:PropertyValue ;
    schema:propertyID "scales_not_assessed" ;
    schema:value "3"^^xsd:integer ;
    schema:description "Biological scales not assessed: cell, tissue, organ_system. Source: swarm/benchmark/fixtures/gt-l4-t1.json#verdict.scales_not_assessed" .

  sub:pv-exit a schema:PropertyValue ;
    schema:propertyID "cli_exit_code" ;
    schema:value "1"^^xsd:integer ;
    schema:description "Exit code of this run: 0 all gates passed, 1 any gate failed, 2 nothing failed but something could not be assessed. Source: sim-engine/validate-cli.mjs:17" .
}

sub:provenance {
  sub:assertion prov:wasAttributedTo <https://w3id.org/delphi/resource/agent/part-2-drafting-agent> ;
    prov:wasDerivedFrom
      <swarm/benchmark/fixtures/gt-l4-t1.json#results> ,
      <swarm/benchmark/fixtures/gt-l4-t1.json#composite_score_from_the_scorer> ,
      <swarm/benchmark/fixtures/gt-l4-t1.json#verdict.word_validated_withheld> ,
      <swarm/benchmark/fixtures/gt-l4-t1.json#verdict.withheld_because> ,
      <swarm/benchmark/fixtures/gt-l4-t1.json#verdict.scales_not_assessed> ,
      <sim-engine/validate-cli.mjs:17> .
}

